readme += '\nCurrent account: approved 3% DD / 1% recovery risk combo; see HTML method for settings.\n'
(OUT/'README.txt').write_text(readme,encoding='utf-8')
with zipfile.ZipFile(OUT/'trade-statistics-complete.zip','w',zipfile.ZIP_DEFLATED) as z:
    for p in sorted(OUT.iterdir()):
        if p.name.startswith('account_') and p.name != f'account_{account_count}_trades.csv': continue
        if p.suffix in ('.csv','.html','.json','.txt'): z.write(p,p.name)
print('Created complete HTML report and CSV download pack.')
